//! Differential test: `hreflang_code::code_error` against the reference baseline, 0 mismatches.
//!
//! Fixture: `fixtures/hreflang_code_oracle.json`, generated by the reference suite.

use serde_json::Value;
use spiderhead_parse::hreflang_code::code_error;

const FIXTURE: &str = include_str!("fixtures/hreflang_code_oracle.json");

#[test]
fn code_error_has_zero_mismatches_against_the_oracle() {
    let rows: Vec<Value> = serde_json::from_str(FIXTURE).unwrap_or_default();
    assert!(rows.len() >= 300, "fixture too small: {}", rows.len());
    let mut mismatches = Vec::new();
    for row in &rows {
        let input = row.get("input").and_then(Value::as_str).unwrap_or_default();
        let want = row.get("error").and_then(Value::as_str).unwrap_or_default();
        let got = code_error(input).unwrap_or_default();
        if got != want {
            mismatches.push(format!("{input:?}: got {got:?}, want {want:?}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{mismatches:#?}",
        mismatches.len()
    );
}
